  fs.writeFileSync(manifest, JSON.stringify(pkg))
  const result = runWorkspaceInitializer(gitRoot)
  assert.equal(result.status, 0, result.stdout + result.stderr)
  assert.match(result.stdout, /将覆盖为默认配置/)
